window.BookBodyFigures=[{"id":"body-figure-1-diversity-0","renderer":"1-diversity-0","chapter":1,"page":"index.html","anchor":"diversity","title":"形态分类关系图","production":"code","caption":"四格并排比较结构：椭圆 E 是一个整体椭球恒星系统，本图不分解核球/盘；S0、S、SB 有盘和中心致密成分，S 与 SB 还有盘内旋臂，SB 另有棒。点选部件可只保留该部件，点击格子读取该类的部件清单。格子之间没有时间箭头，形态分类不代表年龄顺序。","scope":"保留盘、核球与棒的分类；E 只画整体椭球、不声称有独立核球；旋臂只称盘内结构，密度波仅作为一种解释；不用单向箭头把形态串成时间线。","sourceKey":"diversity","sourceLabel":"Mo, van den Bosch & White (2010) · 第 1 章 · pp.2–5"},{"id":"body-figure-1-clocks-1","renderer":"1-clocks-1","chapter":1,"page":"index.html","anchor":"clocks","title":"恒星先出生，星系后组装","production":"code","caption":"跟着同一批彩色圆点看：恒星的出生时间，和它们汇集到同一座星系的时间，是两回事。","scope":"三阶段追踪同一批已有恒星，区分恒星出生与星系质量组装；圆点颜色标出生地，不编码年龄或温度；此例不画新增恒星，未指定真实年代或并合率。","sourceKey":"clocks","sourceLabel":"Mo, van den Bosch & White (2010) · 第 1 章 · pp.14–15"},{"id":"body-figure-2-observing-2","renderer":"2-observing-2","chapter":2,"page":"chapter-2.html","anchor":"observing","title":"同一座星系，三种波段","production":"observation","caption":"这是同一目标 M51 的真实观测图。可见光显示恒星光和尘埃暗带；紫外图突出高温年轻恒星群，伴星在这一波段较暗；8 微米红外图突出尘埃相关辐射。绿、蓝、红是发布方为不同波段指定的显示色，不是肉眼颜色。","scope":"使用真实同一目标与匹配视场，注明波段、仪器、伪彩色和来源。","sourceKey":"measurement","sourceLabel":"Mo, van den Bosch & White (2010) · 第 2 章 · pp.25–34","question":"对照主星系的旋臂与上方伴星：哪些结构在可见光中明亮，却在紫外图中较暗？为什么不能只凭一幅图判断恒星质量分布？","observationNote":"采用发布方同一多波段合成图的分层导出，保持整幅画面，不另行裁剪。可作同视野形态对照；不同仪器分辨率、曝光、显示拉伸和波段响应不同，亮度不能直接横向定量比较。AVM 参考尺寸与网页 JPEG 的长宽比有小幅差别，不能据此把网页像素当作精密天球坐标。","sourceURL":"https://chandra.harvard.edu/photo/2015/iyl/more.html","releaseDate":"2015-01-22","policySources":[{"url":"https://chandra.harvard.edu/photo/image_use.html","basis":"Chandra/SAO content may be reused under NASA guidelines with all appropriate acknowledgements; third-party material retains its own terms. Preserve each exact panel credit."},{"url":"https://www.nasa.gov/nasa-brand-center/images-and-media/","basis":"NASA guidelines permit factual educational uses including textbooks and websites without explicit permission, with source acknowledgement, subject to third-party exceptions and no implied endorsement."},{"url":"https://esahubble.org/copyright/","basis":"ESA/Hubble materials are released under CC BY 4.0 with clear, visible, unaltered full credits. The matching 2008 NGC 1275 observation and composite are also published by ESA/Hubble; their pages are listed below."}],"images":[{"id":"m51-optical","original_image_url":"https://chandra.harvard.edu/photo/2015/iyl/iyl_m51_optical.jpg","width":600,"height":864,"band":"Optical V-band; AVM central wavelength 555 nm","instrument":"Hubble ACS/WFC","display_color":"Green, assigned by original release","credit":"Optical: NASA/STScI","reuse_basis":"NASA/STScI educational outreach image, supplied in the official Chandra release; NASA educational media guidelines and Chandra image-use policy. HubbleSite copyright URL currently redirects to NASA media guidelines.","alt_zh":"M51 的哈勃可见光观测，以绿色显示，主星系的明亮核、旋臂和尘埃暗带清楚，上方有较亮伴星。","sha256":"567e2e227fda4e2fef6f22b33fe99686f3bc102567c31815aed58f3afcb87568","bytes":516719,"path":"assets/observations/m51-optical.jpg","fullPath":"assets/observations/m51-optical.jpg","label":"可见光 · 555 nm","alt":"M51 的哈勃可见光观测，以绿色显示，主星系的明亮核、旋臂和尘埃暗带清楚，上方有较亮伴星。","description":"Hubble ACS/WFC"},{"id":"m51-ultraviolet","original_image_url":"https://chandra.harvard.edu/photo/2015/iyl/iyl_m51_uv.jpg","width":600,"height":864,"band":"Far-ultraviolet; AVM central wavelength 150 nm","instrument":"GALEX FUV","display_color":"Blue, assigned by original release","credit":"UV: NASA/JPL-Caltech","reuse_basis":"NASA GALEX educational outreach image supplied in the official Chandra release; NASA educational media guidelines and Chandra image-use policy.","alt_zh":"M51 的 GALEX 远紫外观测，以蓝色显示，旋臂中的年轻恒星区域呈斑块状，上方伴星很暗。","sha256":"3e227304c339595e198e5efae4c67037b897b09d28d30e379ca648c2d6fdfa20","bytes":160071,"path":"assets/observations/m51-ultraviolet.jpg","fullPath":"assets/observations/m51-ultraviolet.jpg","label":"远紫外 · 150 nm","alt":"M51 的 GALEX 远紫外观测，以蓝色显示，旋臂中的年轻恒星区域呈斑块状，上方伴星很暗。","description":"GALEX FUV"},{"id":"m51-infrared","original_image_url":"https://chandra.harvard.edu/photo/2015/iyl/iyl_m51_ir.jpg","width":600,"height":864,"band":"Mid-infrared; AVM central wavelength 8000 nm = 8 micrometres","instrument":"Spitzer IRAC","display_color":"Red, assigned by original release","credit":"IR: NASA/JPL-Caltech","reuse_basis":"NASA Spitzer educational outreach image supplied in the official Chandra release; NASA educational media guidelines and Chandra image-use policy.","alt_zh":"M51 的斯皮策 8 微米红外观测，以红色显示，旋臂呈细碎明亮的尘埃辐射结构。","sha256":"65f20ea270834815575961b19ba1cc913897e96e062868c116386f9db1b3cbd2","bytes":289434,"path":"assets/observations/m51-infrared.jpg","fullPath":"assets/observations/m51-infrared.jpg","label":"中红外 · 8 μm","alt":"M51 的斯皮策 8 微米红外观测，以红色显示，旋臂呈细碎明亮的尘埃辐射结构。","description":"Spitzer IRAC"}]},{"id":"body-figure-2-stars-3","renderer":"2-stars-3","chapter":2,"page":"chapter-2.html","anchor":"stars","title":"赫罗图：主序、巨星与白矮星","production":"code","caption":"横轴是表面温度（向右降低），纵轴是相对太阳的光度（对数）。三条有宽度的合成教学带比较主序、巨星与白矮星；散点不是真实恒星或星表。可高亮类型、在同一温度上比较三种半径，或定位太阳。","scope":"全部散点、三条带与同温对照都是合成教学模型，不对应真实恒星、星表或观测样本；点的数量不是星数统计。横轴为 T/K 的对数标度且向右降低，纵轴为 L/L☉ 的对数标度。点颜色只是温度的示意映射；圆点大小相同，不表示半径。等半径虚线严格由黑体球面有效温度关系 L/L☉=(R/R☉)²(T/5772 K)⁴ 计算，显示 R=0.01、0.1、1、10、100 R☉。太阳取 T=5772 K（IAU 2015 B3 名义值）、L/L☉=1；同温对照另取 0.01、1、30 R☉。三条带是类型范围的教学参数化，不是演化轨迹，也不画类型之间的演化箭头。参考：https://arxiv.org/abs/1510.07674。","sourceKey":"stellar-observations","sourceLabel":"Mo, van den Bosch & White (2010) · 第 2 章 · pp.34–37"},{"id":"body-figure-3-distance-4","renderer":"3-distance-4","chapter":3,"page":"chapter-3.html","anchor":"distance","title":"发射与接收时刻的距离几何","production":"code","caption":"左格是共动坐标：两行用同一套刻度，χ 不变；右格把同一对位置的物理间距按 aχ 画成独立的尺，拖动 aₑ 可以看到物理间距变化而共动格不动。下排把角大小、通量和 z=1 时三种距离的定义直接画出来。","scope":"共动坐标与物理间距分面显示，不拉伸共动轴冒充物理轴；D_A、D_L 是观测关系定义，不画成同一时刻的四根尺；z=1 数值来自平直 Ωm=0.3 的积分。","sourceKey":"distances","sourceLabel":"Mo, van den Bosch & White (2010) · 第 3 章 · pp.110–124"},{"id":"body-figure-3-distance-5","renderer":"3-distance-5","chapter":3,"page":"chapter-3.html","anchor":"distance","title":"粒子视界、事件视界与哈勃尺度","production":"code","caption":"时间沿纵轴向上，空间沿横轴展开；先找“今天”，再比较三种彩色曲线在这一高度的位置。两条 45° 箭头是到达今天的光路，阴影是能够影响今天的过去光锥。","scope":"在指定膨胀史的共形时空图中画光路，不画宇宙实体边缘。指定运动学模型 a(η)=η/(2−η)，当前 η₀=1、未来 η∞=2；它用于区分三种尺度，不是 ΛCDM 膨胀史。","sourceKey":"distances","sourceLabel":"Mo, van den Bosch & White (2010) · 第 3 章 · pp.110–124"},{"id":"body-figure-4-linear-6","renderer":"4-linear-6","chapter":4,"page":"chapter-4.html","anchor":"linear","title":"声学恢复与无碰撞自由流对照","production":"code","caption":"两格比较同一初始余弦起伏受到的两种作用。灰线是初始状态；流体压力可使起伏反相，无碰撞粒子的自由流则使振幅减小。横轴是位置，不是时间。","scope":"分别标明流体与无碰撞条件，自由流不是粒子接触碰撞。","sourceKey":"linear-jeans","sourceLabel":"Mo, van den Bosch & White (2010) · 第 4 章 · pp.162–168"},{"id":"body-figure-4-growth-7","renderer":"4-growth-7","chapter":4,"page":"chapter-4.html","anchor":"growth","title":"同一初始图案的增长因子三帧","production":"code","caption":"三幅图依次对应更晚的时刻，追踪同一共动区域。颜色编码相对平均密度的偏差，不是温度；改变膨胀背景，比较相同初始起伏后来增长了多少。","scope":"由原书式4.72的增长积分计算D₊，早期D₊/a→1。δ=0.08D₊(a)s(x,y)，相位、共动区域和色标固定。三帧是尺度因子a=0.2、0.5、1，不是等间隔宇宙时间。","sourceKey":"growth","sourceLabel":"Mo, van den Bosch & White (2010) · 第 4 章 · pp.172–173","controls":"growth"},{"id":"body-figure-5-ellipsoid-8","renderer":"5-ellipsoid-8","chapter":5,"page":"chapter-5.html","anchor":"ellipsoid","title":"三主轴收缩与片、丝几何","production":"code","caption":"三个主平面轮廓由所列轴比精确投影：实线是 ab 平面，虚线是 ac，点线是 bc。阶段 2 压缩 c、阶段 3 再压缩 b，受压轴的标签会加粗并标 ↓。","scope":"轴比是独立指定的几何状态，未积分椭球动力学；薄片与细丝只说明不同方向压缩的形态；线型用于在重叠处区分三个主平面。","sourceKey":"ellipsoid","sourceLabel":"Mo, van den Bosch & White (2010) · 第 5 章 · pp.226–230"},{"id":"body-figure-5-similarity-9","renderer":"5-similarity-9","chapter":5,"page":"chapter-5.html","anchor":"similarity","title":"示踪壳的穿越与径向次序","production":"code","caption":"左格沿同一颜色追踪一层示踪壳的半径随时间；拖动时间滑块，曲线上的当前点、右格圆环和固定半径标尺同步。交叉前/中/后三个停靠点可以直接切换，看径向次序如何反转而壳身份不变。","scope":"复用固定谐振势中的无碰撞示踪壳模型 q cos+u sin，只截取半径为正的时间段；圆环用固定标尺，不随参数缩放；不充当自相似吸积解。","sourceKey":"similarity","sourceLabel":"Mo, van den Bosch & White (2010) · 第 5 章 · pp.220–226"},{"id":"body-figure-6-lensing-10","renderer":"6-lensing-10","chapter":6,"page":"chapter-6.html","anchor":"lensing","title":"观测者、透镜、源平面与像平面","production":"code","caption":"左格是薄透镜的光路拓扑；右格是二维天空上的角位置：虚线圆是角半径 θE 的参考圆（只描边），β 是未偏折的源位置，θ₊、θ₋ 是两幅像。","scope":"点像由 θ±=[β±√(β²+4θE²)]/2 计算；平面间隔只表示光路拓扑，dLS 不能用 dS−dL 替换；θE 圆不是有限源的环像。","sourceKey":"lens","sourceLabel":"Mo, van den Bosch & White (2010) · 第 6 章 · pp.292–297 · 含勘误"},{"id":"body-figure-6-galaxies-11","renderer":"6-galaxies-11","chapter":6,"page":"chapter-6.html","anchor":"galaxies","title":"真实分布、巡天遮罩与观测目录","production":"code","caption":"三格使用同一批合成点：先看完整分布，再看遮挡与漏检后的目录。空白条带可能来自观测窗口；最后一格加入随机目录，帮助区分窗口形状与真实聚集。","scope":"数据与随机参照匹配窗口和选择函数，不冒充完整巡天管线。","sourceKey":"galaxies","sourceLabel":"Mo, van den Bosch & White (2010) · 第 6 章 · pp.283–292"},{"id":"body-figure-7-progenitors-12","renderer":"7-progenitors-12","chapter":7,"page":"chapter-7.html","anchor":"progenitors","title":"质量守恒的示意并合树","production":"code","caption":"从上往下读，时间越来越晚：连线表示祖先晕并入后代晕。节点数字是占最终质量的比例；每次合并前后质量相加守恒，这是一棵指定的示例树。","scope":"逐节点守恒，标清示意树，不能宣称由现有EPS边际分布还原实际历史。","sourceKey":"halo-progenitor","sourceLabel":"Mo, van den Bosch & White (2010) · 第 7 章 · 原书与范围"},{"id":"body-figure-7-structure-13","renderer":"7-structure-13","chapter":7,"page":"chapter-7.html","anchor":"structure","title":"同一密度律，球形与三轴结构","production":"code","caption":"一次只突出一层等密度面：上半格画当前 m 的三个主平面轮廓，下半格的三条 z=0 截面里粗线对应当前层。切换 m=0.5/1/1.5 可以比较同一密度层在球形与三轴情形下的形状。","scope":"m²=(x/a)²+(y/b)²+(z/c)²，ρ(m)∝[m(1+m)²]⁻¹；两例 abc=1；等密度面不是实体外壳，也未构造子晕或求解自洽势。","sourceKey":"halo-nfw","sourceLabel":"Mo, van den Bosch & White (2010) · 第 7 章 · 原书与范围","retiredGeneratedImages":["halo-shapes"]},{"id":"body-figure-8-feedback-14","renderer":"8-feedback-14","chapter":8,"page":"chapter-8.html","anchor":"feedback","title":"瞬时爆炸与持续风泡的分层对照","production":"code","caption":"两格是不同的注能方式：左格是瞬时爆炸的 Sedov 绝热极限，右格是持续风吹出的热泡。点选一层（外激波、热气体、接触面、反向激波、冷壳），两格同时高亮；在不存在的极限里会标为“无”。","scope":"按各自边界条件绘制；Sedov 极限不人为添加有物理含义的内层，持续风的内侧半径只作分层示意；两者不是同一爆炸的前后两帧，也不冒充数值流体解。","sourceKey":"gas-feedback","sourceLabel":"Mo, van den Bosch & White (2010) · 第 8 章 · 原书与范围"},{"id":"body-figure-8-observations-15","renderer":"8-observations-15","chapter":8,"page":"chapter-8.html","anchor":"observations","title":"恒星之间，还有一片热气体","production":"observation","caption":"英仙座星系团核心的两幅真实观测。哈勃可见光图显示中心星系 NGC 1275、恒星光与细丝；钱德拉 X 射线图显示弥散的高温团内气体，以及中心附近的空腔。紫色是 X 射线的显示色，不能把可见光中较暗的区域理解为空无物质。这里展示的是星系团核心，不是整个星系团。","scope":"匹配视场，注明能段和伪彩色；X射线亮度不直接等于总质量。","sourceKey":"gas-observations","sourceLabel":"Mo, van den Bosch & White (2010) · 第 8 章 · 原书与范围","question":"找到两幅图中相同的中心：X 射线弥散发射是否只存在于可见光明亮的恒星区域？空腔意味着没有气体，还是 X 射线发射较弱？","observationNote":"采用同一发布中合成图的可见光与 X 射线分层导出，整幅保留，中心与朝向一致。主发布给出的视野宽约 3.87 角分，展示中心星系及其周围热气体。发布图、AVM 参考尺寸与网页导出之间存在尺寸舍入差异，因此适于形态教学，不适于按 JPEG 像素精确量角或测光。不同波段的亮度拉伸和角分辨率不同。","sourceURL":"https://chandra.harvard.edu/photo/2008/perseus/more.html","releaseDate":"2008-08-20","policySources":[{"url":"https://chandra.harvard.edu/photo/image_use.html","basis":"Chandra/SAO content may be reused under NASA guidelines with all appropriate acknowledgements; third-party material retains its own terms. Preserve each exact panel credit."},{"url":"https://www.nasa.gov/nasa-brand-center/images-and-media/","basis":"NASA guidelines permit factual educational uses including textbooks and websites without explicit permission, with source acknowledgement, subject to third-party exceptions and no implied endorsement."},{"url":"https://esahubble.org/copyright/","basis":"ESA/Hubble materials are released under CC BY 4.0 with clear, visible, unaltered full credits. The matching 2008 NGC 1275 observation and composite are also published by ESA/Hubble; their pages are listed below."}],"images":[{"id":"perseus-optical","original_image_url":"https://chandra.harvard.edu/photo/2008/perseus/perseus_optic.jpg","width":720,"height":564,"band":"Optical B/V/r; AVM central wavelengths 435/550/625 nm","instrument":"Hubble ACS","credit":"NASA/ESA/Hubble Heritage (STScI/AURA) & Univ. of Cambridge/IoA/A. Fabian","reuse_basis":"Official NASA/ESA Hubble observation. NASA educational media guidelines; corresponding observation also available through ESA/Hubble under its CC BY 4.0 reuse policy. Preserve the exact Chandra panel credit above and link both the source and applicable reuse policy.","alt_zh":"英仙座星系团核心 NGC 1275 的哈勃可见光图，明亮椭圆状星系周围分布红色细丝和前景点源。","sha256":"7bce76b920c933f6cf3f596a6095572313d439557a76bf35514890fde43a016b","bytes":507891,"path":"assets/observations/perseus-optical.jpg","fullPath":"assets/observations/perseus-optical.jpg","label":"可见光 · B/V/r","alt":"英仙座星系团核心 NGC 1275 的哈勃可见光图，明亮椭圆状星系周围分布红色细丝和前景点源。","description":"Hubble ACS"},{"id":"perseus-xray","original_image_url":"https://chandra.harvard.edu/photo/2008/perseus/perseus_xray.jpg","width":720,"height":564,"band":"X-ray 0.3–7 keV (main release)","instrument":"Chandra ACIS","display_color":"Violet, assigned by original release","credit":"NASA/CXC/IoA/A.Fabian et al","reuse_basis":"NASA/SAO Chandra outreach material; Chandra image-use policy and NASA educational media guidelines with source acknowledgement.","alt_zh":"英仙座星系团核心的钱德拉 X 射线图，以紫色显示弥散高温气体，中心点源两侧可见较暗空腔。","sha256":"01570fa9a6ac659ad598d1ee6e5e6d2ce2392abe4c0540ccbc327c99bc2cb46d","bytes":244964,"path":"assets/observations/perseus-xray.jpg","fullPath":"assets/observations/perseus-xray.jpg","label":"X 射线 · 0.3–7 keV","alt":"英仙座星系团核心的钱德拉 X 射线图，以紫色显示弥散高温气体，中心点源两侧可见较暗空腔。","description":"Chandra ACIS"}]},{"id":"body-figure-9-individual-16","renderer":"9-individual-16","chapter":9,"page":"chapter-9.html","anchor":"individual","title":"从包层到恒星：三个独立尺度","production":"code","caption":"三个视野 A→B→C 依次取景放大：A 的框是盘所在的区域，B 的框是中心恒星所在的区域。三格各自独立比例，箭头只表示“这里再放大看”，不标定倍率。","scope":"每幅独立放大，未给无来源的半径；取景箭头只表示取景关系，不是同一比例尺；外流方向沿盘面法向，箭头不表示磁流体解。","sourceKey":"individual","sourceLabel":"Mo, van den Bosch & White (2010) · 第 9 章 · 原书与范围","retiredGeneratedImages":["protostar-flow-v2"]},{"id":"body-figure-9-molecules-17","renderer":"9-molecules-17","chapter":9,"page":"chapter-9.html","anchor":"molecules","title":"云边缘到内部的解离与遮蔽","production":"code","caption":"两格是同一云中两种遮蔽机制的教学光谱：尘埃让整段紫外/教学波段平滑变暗，H₂ 只在离散谱线内吸收、线间几乎透明。拖动光深 τ₀ 和波长 λ，读数给出同一位置的 τ 与透射率。","scope":"使用明确写出的教学光深模型（尘埃 τ=τ₀·0.15μm/λ；H₂ 七条示意线），不是化学网络、观测谱或真实柱密度反演；谱线位置与宽度仅为示意。","sourceKey":"molecules","sourceLabel":"Mo, van den Bosch & White (2010) · 第 9 章 · 原书与范围"},{"id":"body-figure-10-tracks-18","renderer":"10-tracks-18","chapter":10,"page":"chapter-10.html","anchor":"tracks","title":"演化路径、等龄线与主序转折","production":"code","caption":"左格是同龄星群：哪些质量还在主序上，转折质量随年龄移动；中格是所选质量的主序阶段与年龄；右格是同一寿命拟合给出的转折质量曲线。拖动年龄、点选质量，三格同步。","scope":"沿用第2章赫罗图的温度方向、L/L☉ 对数轴与配色；质量在主序上的位置来自教学映射表，只用于显示谁还在主序，不构成等龄线；没有轨迹库，后主序时长与轨迹未计算。","sourceKey":"tracks","sourceLabel":"Mo, van den Bosch & White (2010) · 第 10 章 · 原书与范围"},{"id":"body-figure-10-chemistry-19","renderer":"10-chemistry-19","chapter":10,"page":"chapter-10.html","anchor":"chemistry","title":"封闭、外流与流入箱的质量和金属账","production":"code","caption":"每格都从气体库沿箭头读：气体形成恒星，一部分回到气体库，其余锁在长寿命恒星与遗迹中。并排比较封闭、外流和流入条件，金属跟随对应的物质流转移。","scope":"箭头与既有化学箱方程一致，分别标气体、恒星、金属，避免只重复Z曲线。","sourceKey":"chemistry","sourceLabel":"Mo, van den Bosch & White (2010) · 第 10 章 · 原书与范围"},{"id":"body-figure-11-instability-20","renderer":"11-instability-20","chapter":11,"page":"chapter-11.html","anchor":"instability","title":"轴对称盘与有棒盘的面密度","production":"code","caption":"两格总质量相同，颜色使用同一面密度标尺：比较把部分盘质量放入棒状分布后形态怎样改变。这是两个指定模型的对照，没有模拟棒随时间长出来。","scope":"指数盘与椭圆Gaussian棒均独立质量归一；颜色为固定范围的对数面密度。该构造不求解棒不稳定或角动量交换。","sourceKey":"instability","sourceLabel":"Mo, van den Bosch & White (2010) · 第 11 章 · 原书与范围","retiredGeneratedImages":["barred-disk"]},{"id":"body-figure-11-exponential-21","renderer":"11-exponential-21","chapter":11,"page":"chapter-11.html","anchor":"exponential","title":"同一盘模型的正面与侧面视图","production":"code","caption":"两格是同一盘从正面和侧面看：正面显示径向尺度，侧面显示厚度。颜色分别除以各自中心投影密度；同样的颜色不表示两幅图具有相同的绝对亮度。","scope":"从同一密度模型投影，区分光度和质量，不再重复已有斜视封面。","sourceKey":"exponential","sourceLabel":"Mo, van den Bosch & White (2010) · 第 11 章 · 原书与范围"},{"id":"body-figure-12-clusters-22","renderer":"12-clusters-22","chapter":12,"page":"chapter-12.html","anchor":"clusters","title":"潮汐、冲压和断供：三种不同机制","production":"code","caption":"三格是三种不同机制：潮汐曲线是同一时刻不同位置的受力差（横轴是位置，不是时间）；冲压图里椭圆是恒星主体、蓝箭头是团内气体来流、蓝曲线是被剥离的盘气体与尾迹；断供格横轴才是时间。","scope":"潮汐用外部点质量轴向差分；冲压轮廓只示意组分与来流方向，未计算剥离形状；断供用固定回流率与耗气时标的指数解。","sourceKey":"clusters","sourceLabel":"Mo, van den Bosch & White (2010) · 第 12 章 · 原书与范围","retiredGeneratedImages":["environment-tides","environment-ram","environment-starvation"]},{"id":"body-figure-12-dynamical-friction-23","renderer":"12-dynamical-friction-23","chapter":12,"page":"chapter-12.html","anchor":"dynamical-friction","title":"卫星运动与引力尾迹","production":"code","caption":"卫星向右运动，把背景粒子拉向自己后方形成过密尾迹；尾迹对卫星的平均作用力与运动方向相反。可开关橙色的示意偏折路径。","scope":"区分引力响应与气体阻力；尾迹与偏折路径都是概念示意，未自洽求解背景分布函数，也不含气体。","sourceKey":"dynamical-friction","sourceLabel":"Mo, van den Bosch & White (2010) · 第 12 章 · 原书与范围"},{"id":"body-figure-13-structure-24","renderer":"13-structure-24","chapter":13,"page":"chapter-13.html","anchor":"structure","title":"三轴势中的箱轨道与管轨道","production":"code","caption":"两条轨道都来自同一固定三轴势的数值积分。拖动时间滑块，粗线走到当前时刻，箭头给出运动方向，读数给出当前 Lz——箱轨道的 Lz 会变号，管轨道保持为正。","scope":"复用已积分的轨迹，滑块只截取同一段积分；绘出 x–y 投影；不把单条轨道当作整个星系的自洽模型。","sourceKey":"structure","sourceLabel":"Mo, van den Bosch & White (2010) · 第 13 章 · 原书与范围"},{"id":"body-figure-13-plane-25","renderer":"13-plane-25","chapter":13,"page":"chapter-13.html","anchor":"plane","title":"基本平面及二维投影","production":"code","caption":"25 个合成点严格位于 r=1.25s−0.8125i 的平面上。左格是斜投影，右格是 s–r 二维投影；颜色是第三变量 i。收窄切片窗口，可以看到二维图上的散开完全来自被略去的 i；点选同一点会在两图同时标出。","scope":"保留合成网格、零内禀散布与既有关系；颜色按 i 着色；不加入测量误差，不冒充观测样本。","sourceKey":"plane","sourceLabel":"Mo, van den Bosch & White (2010) · 第 13 章 · 原书与范围"},{"id":"body-figure-14-engine-26","renderer":"14-engine-26","chapter":14,"page":"chapter-14.html","anchor":"engine","title":"吸积盘、广线区、尘埃环与窄线区分层","production":"code","caption":"空间剖面：中心是黑洞与吸积盘，宽线区在盘上方靠近中心，尘埃环在更外的赤道面，窄线区沿极向延伸到更远。拖动视线倾角，可以看到宽线区何时被尘埃环挡住、而窄线区仍然可见。","scope":"同一视野内只比较相对位置，半径不按比例；尘埃环张角由图中厚度/半径得出，仅作示意；喷流是可选部件，不是所有 AGN 都有。","sourceKey":"engine","sourceLabel":"Mo, van den Bosch & White (2010) · 第 14 章 · 原书与范围"},{"id":"body-figure-14-engine-27","renderer":"14-engine-27","chapter":14,"page":"chapter-14.html","anchor":"engine","title":"反响映射的光路差与时延","production":"code","caption":"先比较从中心直接到观察者的闪光，与先照亮球壳再到观察者的光。τ是相对直接闪光多等的时间：近侧几乎不额外绕路，远侧多走2r；另一格把这个关系画成曲线。","scope":"与现有环模型和延迟定义一致，不能用装饰性同心圆代替等时延几何。","sourceKey":"engine","sourceLabel":"Mo, van den Bosch & White (2010) · 第 14 章 · 原书与范围"},{"id":"body-figure-15-distribution-28","renderer":"15-distribution-28","chapter":15,"page":"chapter-15.html","anchor":"distribution","title":"联合分布与边缘投影","production":"code","caption":"三格使用同一批96个合成点：先看质量与颜色的配对关系，再分别统计两者的数量分布。后两格丢失了“哪种质量对应哪种颜色”的信息，不是另两个时刻的样本。","scope":"所有投影来自同一批合成或真实数据，无来源的蓝云红序列不能标为实测。","sourceKey":"distribution","sourceLabel":"Mo, van den Bosch & White (2010) · 第 15 章 · 原书与范围"},{"id":"body-figure-15-clustering-29","renderer":"15-clustering-29","chapter":15,"page":"chapter-15.html","anchor":"clustering","title":"相同平均占据、不同成对数的分组","production":"code","caption":"两组都有 4 座晕、8 个星系，平均每晕 2 个，但 A 每晕恰好一对、B 的成员集中在两座晕里；青线连接每一对成员，格内直接给出本组配对总数。","scope":"画出具体宿主与成员并逐对计数；未加入质量分布、内部径向分布或晕偏倚。","sourceKey":"clustering","sourceLabel":"Mo, van den Bosch & White (2010) · 第 15 章 · 原书与范围"},{"id":"body-figure-16-lyman-forest-30","renderer":"16-lyman-forest-30","chapter":16,"page":"chapter-16.html","anchor":"lyman-forest","title":"前景气体与合成吸收线对应图","production":"code","caption":"同一视线的合成密度与透射共用横坐标。移动探针（或聚焦后按左右键）会在两幅图同时标出同一位置，读数给出该处的 Δ 和 F。","scope":"沿用合成森林实验的正密度场并按窗口积分均值归一；幂律密度—光深近似，不含速度场、热展宽或屏蔽。","sourceKey":"lyman-forest","sourceLabel":"Mo, van den Bosch & White (2010) · 第 16 章 · 原书与范围"},{"id":"body-figure-16-limit-systems-31","renderer":"16-limit-systems-31","chapter":16,"page":"chapter-16.html","anchor":"limit-systems","title":"Lyα森林、LLS与DLA的分类关系","production":"code","caption":"同一柱密度轴上的三种系统：低柱密度的森林、广义 LLS（Lyman 边缘光深约为 1）、以及包含在其内部的 DLA。橙色虚线标出 DLA 在 LLS 内的范围。","scope":"广义 LLS 包含 DLA，不是互斥三组；阈值可依目录约定不同；图中不计算阻尼翼。","sourceKey":"limit-systems","sourceLabel":"Mo, van den Bosch & White (2010) · 第 16 章 · 原书与范围"},{"id":"body-figure-3-planck-cmb-2013","chapter":3,"page":"chapter-3.html","anchor":"thermal","title":"微波背景：整片天空的温度起伏","production":"observation","kindLabel":"观测数据产品 · 全天投影","caption":"Planck 的微波观测经前景分离后，得到这幅微波背景温度各向异性全天图。橙红与蓝色编码相对较热与较冷的温度起伏；椭圆是把整片天空展开到平面的投影，不是宇宙的外形或边界。","scope":"这是一份处理后的观测产品，不是直接的早期物质密度照片。温度起伏还包含声学、速度及引力等效应，不能把颜色逐像素等同于密度。网页图没有数值色标，不用于读取微开尔文温差、测角或拟合宇宙学参数。2013 年观测作为 2010 年教材主题的补充，不改写实验参数。","sourceLabel":"原书主题：MBW（2010）§3.3–3.5，pp.124–152；2013 年观测补充","question":"把它与热历史节点对照：我们接收到的是不同天球方向的早期辐射，还是同一时刻宇宙的三维俯视图？","observationNote":"保持发布方整幅 JPEG 与显示色，不裁剪、不改色。本图用于观测图景与模型的对照，不从网页像素进行测光或参数估计。","sourceURL":"https://www.esa.int/ESA_Multimedia/Images/2013/03/Planck_CMB","releaseDate":"2013-03-21","policySources":[{"url":"https://www.esa.int/ESA_Multimedia/Terms_and_conditions_of_use_of_images_and_videos_available_on_the_esa_website","label":"ESA 教育使用说明","basis":"Educational use of this ESA/Planck image with full credit under the ESA Standard Licence; no endorsement implied."}],"images":[{"id":"planck-cmb-2013","path":"assets/observations/planck-cmb-2013.jpg","bytes":2373272,"width":1920,"height":960,"sha256":"75a2ecdd593ccaf092ffe7a594c5283fd6d6529ed084d063956deb8859ed4448","original_image_url":"https://www.esa.int/var/esa/storage/images/esa_multimedia/images/2013/03/planck_cmb/12583930-4-eng-GB/Planck_CMB.jpg","fullPath":"assets/observations/planck-cmb-2013.jpg","label":"Planck · 2013 年温度各向异性图","alt":"Planck 的微波背景全天温度起伏图：椭圆投影内布满橙红与蓝色斑纹，外围白色区域不代表天体或天空边界。","alt_zh":"Planck 的微波背景全天温度起伏图：椭圆投影内布满橙红与蓝色斑纹，外围白色区域不代表天体或天空边界。","description":"Planck；前景分离后的微波背景温度产品","credit":"ESA and the Planck Collaboration (© ESA)","band":"Microwave, foreground-separated CMB temperature product","instrument":"Planck；前景分离后的微波背景温度产品","display_color":"Orange/red and blue encode relatively warmer and cooler temperature fluctuations, not visible-light colors.","reuse_basis":"Educational use of this ESA/Planck image with full credit under the ESA Standard Licence; no endorsement implied.","distribution":"external_reference_only","distribution_note":"公开源码及离线包不分发此ESA Standard Licence图像；保留官方观测链接。"}]},{"id":"body-figure-6-cosmic-horseshoe","chapter":6,"page":"chapter-6.html","anchor":"lensing","title":"宇宙马蹄：真实天空中的透镜弧","production":"observation","kindLabel":"真实观测 · 可见光与近红外合成","caption":"画面右侧偏下的红色前景星系外，蓝色背景星系的光被引力偏折，形成近乎闭合的马蹄形透镜弧。这条弧是背景源的像，不能当作环绕前景星系的物质环或恒星轨道。","scope":"该图采用发布方的可见光与近红外合成。实际透镜是有延展结构的星系，不能直接用本章点质量模型拟合；有限源大小、透镜质量分布与对齐程度都会影响像。网页图仅供形态对照，不从环半径读取质量，也不凭显示颜色确定年龄。","sourceLabel":"原书主题：MBW（2010）§6.6，pp.292–297；真实星系透镜补充","question":"先找到红色透镜星系，再沿蓝色弧追踪背景源的像；它与理想点质量实验中的完全对齐环有什么相似和不同？","observationNote":"保持发布方整幅 JPEG 与显示色，不裁剪、不改色。本图用于观测图景与模型的对照，不从网页像素进行测光或参数估计。","sourceURL":"https://esahubble.org/images/potw1151a/","releaseDate":"2011-12-19","policySources":[{"url":"https://esahubble.org/copyright/","label":"ESA/Hubble · CC BY 4.0","basis":"Official ESA/Hubble images may be reused under CC BY 4.0 with the full unaltered credit visible and linked."}],"images":[{"id":"cosmic-horseshoe","path":"assets/observations/cosmic-horseshoe.jpg","bytes":235612,"width":1280,"height":1018,"sha256":"5a365f2637d65f76d11f58d0a46f150dbe76db5705027682d6cd6d381553c91c","original_image_url":"https://cdn.esahubble.org/archives/images/screen/potw1151a.jpg","fullPath":"assets/observations/cosmic-horseshoe.jpg","label":"宇宙马蹄 · Hubble WFC3","alt":"哈勃观测中的宇宙马蹄：画面右侧偏下的红色前景星系被一条蓝色、近乎闭合的背景星系透镜弧包围。","alt_zh":"哈勃观测中的宇宙马蹄：画面右侧偏下的红色前景星系被一条蓝色、近乎闭合的背景星系透镜弧包围。","description":"Hubble WFC3；可见光 B/V 与近红外 I 波段合成","credit":"ESA/Hubble & NASA","band":"Optical B/V and near-infrared I, Hubble WFC3","instrument":"Hubble WFC3；可见光 B/V 与近红外 I 波段合成","display_color":"Published optical/infrared composite; display colors are not direct measurements of age or mass.","reuse_basis":"Official ESA/Hubble images may be reused under CC BY 4.0 with the full unaltered credit visible and linked."}]},{"id":"body-figure-7-bullet-cluster-composite","chapter":7,"page":"chapter-7.html","anchor":"structure","title":"子弹星系团：气体与透镜质量的错位","production":"observation","kindLabel":"多波段观测＋质量反演","caption":"发布方把三种证据叠加在同一视野：白橙色是光学天体，粉色是 X 射线发射的热气体，蓝色是由背景天体形变重建的投影质量分布。热气体与主要质量集中区的错位，是研究暗物质的重要观测证据。","scope":"蓝色不是暗物质的直接照片，也不是纯暗物质密度的逐像素测量；透镜反演约束视线方向上投影的总质量，并有模型与测量不确定性。这是碰撞中的非平衡星系团，不能把平滑、球对称、平衡的 NFW 图景机械套用到整个系统，也不能用此图直接读出暗物质自相互作用截面。","sourceLabel":"原书主题：MBW（2010）§7.5，暗晕内部结构；碰撞观测补充","question":"先区分发光气体与重建质量，再比较它们的位置；蓝色层是望远镜直接拍到的暗物质发光吗？","observationNote":"保持发布方整幅 JPEG 与显示色，不裁剪、不改色。蓝色层为透镜质量反演，不能当作直接成像。","sourceURL":"https://chandra.harvard.edu/photo/2006/1e0657/","releaseDate":"2006-08-21","policySources":[{"url":"https://chandra.harvard.edu/photo/image_use.html","basis":"Chandra/SAO content may be reused under NASA guidelines with all appropriate acknowledgements; third-party material retains its own terms. Preserve each exact panel credit.","label":"Chandra 图像使用说明"},{"url":"https://www.nasa.gov/nasa-brand-center/images-and-media/","basis":"NASA guidelines permit factual educational uses including textbooks and websites without explicit permission, with source acknowledgement, subject to third-party exceptions and no implied endorsement.","label":"NASA 图像政策"}],"images":[{"id":"bullet-cluster-composite","path":"assets/observations/bullet-cluster-composite.jpg","bytes":484920,"width":720,"height":520,"sha256":"7929c07bf960ca90eeb759f59085eb7faa25df6f50bda5edc71b64f5a32e298b","original_image_url":"https://chandra.harvard.edu/photo/2006/1e0657/1e0657.jpg","fullPath":"assets/observations/bullet-cluster-composite.jpg","label":"子弹星系团 · 光学 / X 射线 / 透镜质量","alt":"子弹星系团合成观测：白橙色光学天体背景上叠加粉色热气体和两侧蓝色透镜质量重建区域，它们的主要集中位置不同。","alt_zh":"子弹星系团合成观测：白橙色光学天体背景上叠加粉色热气体和两侧蓝色透镜质量重建区域，它们的主要集中位置不同。","description":"Chandra ACIS + Hubble/Magellan 光学观测 + 引力透镜质量重建","credit":"X-ray: NASA/CXC/CfA/M.Markevitch et al.; Optical: NASA/STScI; Magellan/U.Arizona/D.Clowe et al.; Lensing Map: NASA/STScI; ESO WFI; Magellan/U.Arizona/D.Clowe et al.","band":"Optical, X-ray, and reconstructed projected lensing mass","instrument":"Chandra ACIS + Hubble/Magellan 光学观测 + 引力透镜质量重建","display_color":"Pink: X-ray emitting hot gas; blue: lensing-derived projected mass; optical: white/orange galaxies.","reuse_basis":"Chandra/SAO content may be reused under NASA guidelines with all appropriate acknowledgements; third-party material retains its own terms. Preserve each exact panel credit."}]},{"id":"body-figure-15-coma-cluster-field","chapter":15,"page":"chapter-15.html","anchor":"environmental-dependence","title":"后发座星系团：环境中的星系样本","production":"observation","kindLabel":"真实观测 · 星系团局部视场","caption":"哈勃拍摄的后发座星系团局部视场中，可见多个平滑、偏暖色的星系，也有形态不同的天体。它为“密集环境”提供直观背景，但一张局部照片本身还不是经过选择函数与成员确认的星系目录。","scope":"这不是整个星系团，也不是质量完备样本；前景恒星和背景星系可能进入视野。不能把所有小光点都判作团成员，不能按本图直接计算红色星系比例、成员数或环境淬火效率。星系颜色也不能独自给出年龄，环境相关不等于唯一因果机制。","sourceLabel":"原书主题：MBW（2010）§15.5，pp.674–678；真实星系团局部观测补充","question":"哪些判断可以从形态直接提出，哪些必须加入距离、红移、质量及样本选择后才能比较？","observationNote":"保持发布方整幅 JPEG 与显示色，不裁剪、不改色。本图用于观测图景与模型的对照，不从网页像素进行测光或参数估计。","sourceURL":"https://esahubble.org/images/heic0813a/","releaseDate":"2008-06-10","policySources":[{"url":"https://esahubble.org/copyright/","label":"ESA/Hubble · CC BY 4.0","basis":"Official ESA/Hubble images may be reused under CC BY 4.0 with the full unaltered credit visible and linked."}],"images":[{"id":"coma-cluster-field","path":"assets/observations/coma-cluster-field.jpg","bytes":5884258,"width":4000,"height":2840,"sha256":"996bdfb178dc5e9cc25cd0518ec801e2c2c8dbaa0a02378e0424a56915c32045","original_image_url":"https://cdn.esahubble.org/archives/images/publicationjpg/heic0813a.jpg","fullPath":"assets/observations/coma-cluster-field.jpg","label":"后发座星系团局部 · Hubble ACS","alt":"哈勃后发座星系团局部观测：深色背景中有多座大小不同的暖色平滑星系，以及部分较蓝、扁平或具有旋臂的天体。","alt_zh":"哈勃后发座星系团局部观测：深色背景中有多座大小不同的暖色平滑星系，以及部分较蓝、扁平或具有旋臂的天体。","description":"Hubble ACS；F475W（B）与 F814W（I）合成","credit":"NASA, ESA, and the Hubble Heritage Team (STScI/AURA). Acknowledgment: D. Carter (Liverpool John Moores University) and the Coma HST ACS Treasury Team.","band":"Hubble ACS F475W and F814W","instrument":"Hubble ACS；F475W（B）与 F814W（I）合成","display_color":"Published two-filter optical/near-infrared display composite; not a mass or membership map.","reuse_basis":"Official ESA/Hubble images may be reused under CC BY 4.0 with the full unaltered credit visible and linked."}]},{"id":"body-figure-9-hh30-webb-disk-jet","chapter":9,"page":"chapter-9.html","anchor":"individual","title":"HH 30：尘埃盘与盘面外的喷流","production":"observation","kindLabel":"真实观测 · 红外多波段合成","caption":"HH 30 的红外观测显示近侧视的尘埃盘、盘面外的细喷流，以及更宽的外流和散射星云。中央暗带遮挡了年轻恒星，亮雾状结构仍可呈现被尘埃散射的星光；画面颜色是不同红外波段的显示编码。","question":"先辨认中央暗带，再沿细喷流向上观察：为什么遮挡恒星的尘埃盘周围，仍能看见明亮星云？","scope":"本例是年轻恒星的盘与外流系统，不能把图中的亮区直接当成本节电离氢区实验的均匀球。投影、尘埃散射和不同波段分辨率共同影响外观；不能从显示色直接测温、从暗带宽度直接读盘质量，或把亮结认定为行星。2025 年观测是对 2010 年教材主题的补充。","sourceLabel":"原书主题：MBW（2010）§9.4，pp.429–433；2025 年观测补充","sourceURL":"https://esawebb.org/images/potm2501a/","releaseDate":"2025-02-04","policySources":[{"url":"https://esawebb.org/copyright/","label":"ESA/Webb · CC BY 4.0","basis":"Official ESA/Webb observation; CC BY 4.0, full unaltered linked credit visible beside the image."}],"observationNote":"整幅保留发布方 JPEG、显示色与方向，不裁剪或重绘。显示倍率只改变查看大小，不增加原始分辨率；本图用于形态与物理过程对照。","images":[{"id":"hh30-webb-disk-jet","path":"assets/observations/hh30-webb-disk-jet.jpg","bytes":127060,"sha256":"77f9ab3c7ed003fd12683e486f01575d661f87e0ba7cea3269d6ce5b53b1a2c8","width":1173,"height":1173,"original_image_url":"https://cdn.esawebb.org/archives/images/large/potm2501a.jpg","fullPath":"assets/observations/hh30-webb-disk-jet.jpg","label":"HH 30 · Webb NIRCam / MIRI","description":"Webb NIRCam 与 MIRI；近、中红外波段合成","credit":"ESA/Webb, NASA & CSA, Tazaki et al.","band":"NIRCam 2.0/4.44 micrometres and MIRI 7.7/12/21 micrometres, as listed in the official release","instrument":"Webb NIRCam 与 MIRI；近、中红外波段合成","display_color":"Assigned display colors for several infrared filters; not visible-light colors or a calibrated temperature map.","reuse_basis":"Official ESA/Webb observation; CC BY 4.0, full unaltered linked credit visible beside the image.","alt":"HH 30 的 Webb 红外合成图：中央横向暗尘埃带上下有明亮散射星云，一束细喷流向上延伸，更宽的弥散外流向两侧展开。","alt_zh":"HH 30 的 Webb 红外合成图：中央横向暗尘埃带上下有明亮散射星云，一束细喷流向上延伸，更宽的弥散外流向两侧展开。"}]},{"id":"body-figure-10-tycho-remnant-2019","chapter":10,"page":"chapter-10.html","anchor":"feedback","title":"第谷遗迹：超新星之后的高能物质","production":"observation","kindLabel":"真实观测 · X 射线显示色","caption":"Ia 型第谷超新星遗迹的 X 射线图展示爆炸之后被激波加热、具有团块结构的物质。它把恒星反馈的能量与物质回收连接到可观测遗迹；颜色组合了不同能段和选定硅谱线的多普勒信息，并不是一张统一的温度图。","question":"把明亮外缘与内部团块分开观察：能量源的存在，是否足以说明周围气体最终有多少会逃离星系？","scope":"第谷是 Ia 型白矮星热核爆炸的遗迹，不能混同于大质量恒星的核心坍缩超新星。本图只作反馈过程的观测补充，不能据亮度或表观半径直接读出能量耦合效率、金属产额或套用 IMF 平均的核心坍缩事件率。红蓝也不能逐点当作同一速度标尺；本图采用纯 X 射线图层。","sourceLabel":"原书主题：MBW（2010）§10.5，pp.492–494；Ia 型遗迹观测补充","sourceURL":"https://chandra.harvard.edu/photo/2019/tycho/more.html","releaseDate":"2019-10-17","policySources":[{"url":"https://chandra.harvard.edu/photo/image_use.html","basis":"Chandra/SAO content may be reused under NASA guidelines with all appropriate acknowledgements; third-party material retains its own terms. Preserve each exact panel credit.","label":"Chandra 图像使用说明"}],"observationNote":"整幅保留发布方 JPEG、显示色与方向，不裁剪或重绘。显示倍率只改变查看大小，不增加原始分辨率；本图用于形态与物理过程对照。","images":[{"id":"tycho-remnant-2019","path":"assets/observations/tycho-remnant-2019.jpg","bytes":329729,"sha256":"1f06f6eb8b202f6548d2ee4c4f3508356b7ba9251311803b83a480c246b01846","width":864,"height":865,"original_image_url":"https://chandra.harvard.edu/photo/2019/tycho/tycho_xray.jpg","fullPath":"assets/observations/tycho-remnant-2019.jpg","label":"第谷超新星遗迹 · Chandra X 射线","description":"Chandra ACIS；发布方 X 射线图层","credit":"X-ray: NASA/CXC/RIKEN & GSFC/T. Sato et al","band":"Chandra X-ray broad bands plus selected Doppler-shifted silicon-line bands; optical layer not included","instrument":"Chandra ACIS；发布方 X 射线图层","display_color":"Release-specific X-ray energy and selected silicon Doppler encodings; colors cannot all be interpreted as one temperature or velocity scale.","reuse_basis":"Chandra/SAO content may be reused under NASA guidelines with all appropriate acknowledgements; third-party material retains its own terms. Preserve each exact panel credit.","alt":"第谷超新星遗迹的 Chandra X 射线图：暗背景中有近圆形的明亮外缘与内部多彩团块，颜色来自发布方的能段及部分谱线编码。","alt_zh":"第谷超新星遗迹的 Chandra X 射线图：暗背景中有近圆形的明亮外缘与内部多彩团块，颜色来自发布方的能段及部分谱线编码。"}]},{"id":"body-figure-11-ngc1300-stellar-bar","chapter":11,"page":"chapter-11.html","anchor":"instability","title":"NGC 1300：真实星系中的恒星棒","production":"observation","kindLabel":"真实观测 · 棒旋星系","caption":"明亮恒星棒穿过 NGC 1300 的中心，主要旋臂从棒的两端向外展开；尘埃暗带和斑块状发光区域又给外观增加了层次。这张图为本节轴对称盘与有棒盘的模型对照提供了真实形态参照。","question":"哪些结构明显偏离轴对称？仅凭这张照片，可以测出局部 Toomre Q 或棒的角动量输运率吗？","scope":"恒星光受族群、尘埃消光和投影影响，不能直接等同于质量面密度。程序图中的棒质量份额不是本图的亮度比例；照片本身也不能给出模式速度、稳定性参数或唯一的形成机制。不能由局部轴对称稳定条件推断这根棒必然存在或消失。","sourceLabel":"原书主题：MBW（2010）§11.5，pp.521–531；真实恒星棒形态对照","sourceURL":"https://esahubble.org/images/opo0501a/","releaseDate":"2005-01-11","policySources":[{"url":"https://esahubble.org/copyright/","label":"ESA/Hubble · CC BY 4.0","basis":"Official ESA/Hubble observation; CC BY 4.0, full unaltered linked credit visible beside the image."}],"observationNote":"整幅保留发布方 JPEG、显示色与方向，不裁剪或重绘。显示倍率只改变查看大小，不增加原始分辨率；本图用于形态与物理过程对照。","images":[{"id":"ngc1300-stellar-bar","path":"assets/observations/ngc1300-stellar-bar.jpg","bytes":3825103,"sha256":"631d0559f5c772c6490f760b2f574e8a81da6bc43e422da589986d9f2d0b839b","width":4000,"height":2282,"original_image_url":"https://cdn.esahubble.org/archives/images/publicationjpg/opo0501a.jpg","fullPath":"assets/observations/ngc1300-stellar-bar.jpg","label":"NGC 1300 · Hubble ACS","description":"Hubble ACS；B、V、H-alpha 与 I 波段合成","credit":"NASA, ESA, and The Hubble Heritage Team (STScI/AURA)","band":"Hubble ACS B 435 nm, V 555 nm, H-alpha 658 nm and I 814 nm, official release labels","instrument":"Hubble ACS；B、V、H-alpha 与 I 波段合成","display_color":"Published optical/near-infrared display composite, affected by stellar populations and extinction; not a stellar mass map.","reuse_basis":"Official ESA/Hubble observation; CC BY 4.0, full unaltered linked credit visible beside the image.","alt":"NGC 1300 的哈勃观测：一条暖色恒星棒横穿明亮中心，两条蓝灰色旋臂从棒两端弯曲伸出，盘中可见尘埃暗带。","alt_zh":"NGC 1300 的哈勃观测：一条暖色恒星棒横穿明亮中心，两条蓝灰色旋臂从棒两端弯曲伸出，盘中可见尘埃暗带。"}]},{"id":"body-figure-12-eso137-stripping","chapter":12,"page":"chapter-12.html","anchor":"clusters","title":"ESO 137-001：冲压剥离的观测线索","production":"observation","kindLabel":"真实观测 · 紫外与可见光合成","caption":"ESO 137-001 在星系团环境中留下不对称、带蓝色亮结的延展结构。这些紫外与可见光线索与冲压剥离及尾迹中的恒星形成有关，可与本节迎风剥离模型比较；周围的大量明亮点源不都属于这座星系。","question":"比较主体盘与向一侧延伸的尾迹：它们怎样帮助你区分气体受冲压与恒星受潮汐作用？","scope":"本图并非热团内气体的 X 射线图；蓝色尾迹也不能整体解释成被剥离的既有恒星盘。解释需要多波段与光谱证据，不能从一幅投影照片直接求气体质量、空间速度或冲压强度。冲压与潮汐、断供等机制可能并存，外观不自动证明只有一种机制。","sourceLabel":"原书主题：MBW（2010）§12.5，pp.568–573；冲压剥离观测补充","sourceURL":"https://esahubble.org/images/heic1404a/","releaseDate":"2014-03-04","policySources":[{"url":"https://esahubble.org/copyright/","label":"ESA/Hubble · CC BY 4.0","basis":"Official ESA/Hubble observation; CC BY 4.0, full unaltered linked credit visible beside the image."}],"observationNote":"整幅保留发布方 JPEG、显示色与方向，不裁剪或重绘。显示倍率只改变查看大小，不增加原始分辨率；本图用于形态与物理过程对照。","images":[{"id":"eso137-stripping","path":"assets/observations/eso137-stripping.jpg","bytes":396947,"sha256":"14dd065f5811612f0c0dae8897ec8d6672b79e46ba17983ce2c044698e797fe1","width":1280,"height":875,"original_image_url":"https://cdn.esahubble.org/archives/images/screen/heic1404a.jpg","fullPath":"assets/observations/eso137-stripping.jpg","label":"ESO 137-001 · Hubble WFC3 / ACS","description":"Hubble WFC3 紫外与 ACS 可见光、近红外合成","credit":"NASA, ESA. Acknowledgements: Ming Sun (UAH), and Serge Meunier","band":"Hubble WFC3 U 275 nm and ACS g 475 nm / I 814 nm, official release labels","instrument":"Hubble WFC3 紫外与 ACS 可见光、近红外合成","display_color":"Published ultraviolet/optical/near-infrared display colors; not an X-ray gas density map.","reuse_basis":"Official ESA/Hubble observation; CC BY 4.0, full unaltered linked credit visible beside the image.","alt":"ESO 137-001 的哈勃合成观测：画面中央偏左有星系主体与向右下延展的蓝色斑块和细丝，前景星光及背景天体遍布视野。","alt_zh":"ESO 137-001 的哈勃合成观测：画面中央偏左有星系主体与向右下延展的蓝色斑块和细丝，前景星光及背景天体遍布视野。"}]},{"id":"body-figure-13-eso38112-stellar-shells","chapter":13,"page":"chapter-13.html","anchor":"tests","title":"恒星壳层：重建形成史的一条线索","production":"observation","kindLabel":"真实观测 · 早型星系壳状结构","caption":"透镜状早型星系 ESO 381-12 的平滑主体外，有不对称的淡弱壳状星光边界。这样的残余形态为过去相互作用提供线索，可与本节“用多种证据检验形成理论”的讨论对照；壳层是恒星分布特征，不是实体球壳或气体泡壁。","question":"哪些外层弧状边界偏离了平滑星光分布？为什么看到壳层，仍不能唯一重建并合过程？","scope":"ESO 381-12 被发布方归类为透镜状早型星系；本例不冒充纯椭圆星系的统计样本。仅凭这幅形态图，不能确定唯一的并合质量比、时间、次数或所有恒星的形成年代。淡弱结构的可见性还受曝光、视场、投影与显示拉伸影响。","sourceLabel":"原书主题：MBW（2010）§13.3，pp.594–602；早型星系残余形态补充","sourceURL":"https://esahubble.org/images/heic1516a/","releaseDate":"2015-07-09","policySources":[{"url":"https://esahubble.org/copyright/","label":"ESA/Hubble · CC BY 4.0","basis":"Official ESA/Hubble observation; CC BY 4.0, full unaltered linked credit visible beside the image."}],"observationNote":"整幅保留发布方 JPEG、显示色与方向，不裁剪或重绘。显示倍率只改变查看大小，不增加原始分辨率；本图用于形态与物理过程对照。","images":[{"id":"eso38112-stellar-shells","path":"assets/observations/eso38112-stellar-shells.jpg","bytes":223661,"sha256":"a88cde9320e38c229e3b5fb9a08108f2177c3f1bd07a8a1df4ef572586b08a01","width":1280,"height":1252,"original_image_url":"https://cdn.esahubble.org/archives/images/screen/heic1516a.jpg","fullPath":"assets/observations/eso38112-stellar-shells.jpg","label":"ESO 381-12 · Hubble","description":"Hubble；保留发布方整幅观测合成图","credit":"NASA, ESA, P. Goudfrooij (STScI)","band":"Hubble imaging, as published in the official observation release","instrument":"Hubble；保留发布方整幅观测合成图","display_color":"Published observation display colors; faint stellar shells rather than solid walls or gas bubble boundaries.","reuse_basis":"Official ESA/Hubble observation; CC BY 4.0, full unaltered linked credit visible beside the image.","alt":"哈勃观测中的 ESO 381-12：画面中央的平滑星系被偏心、不对称的淡弱弧状恒星壳层包围，右侧另有较小星系，背景分布许多遥远天体。","alt_zh":"哈勃观测中的 ESO 381-12：画面中央的平滑星系被偏心、不对称的淡弱弧状恒星壳层包围，右侧另有较小星系，背景分布许多遥远天体。"}]}];
